import {ToolRegistry} from './registry.js';

describe('tool validation paths', () => {
  // specs/hal-engine-tool-input-validation/spec.md#2
  it('reports the path and type of a rejected property without its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'weather', description: 'weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
      async () => 'forecast'
    );
    const response = await registry.execute('weather', {location: 123456789});
    expect(response.result).toBe('Invalid tool input: /location must be string');
  });
});
EOF
